files.check.mjs:
import { readFileSync } from "node:fs";
const part=process.argv[2];
const ok=part==="combined"?JSON.parse(readFileSync("generated/index.json","utf8")).every(x=>x.status==="ready"):readFileSync(`features/${part}.mjs`,"utf8").includes('status = "ready"');
console.log({part,ok});process.exitCode=ok?0:1;

files.generate-index.mjs:
import { mkdirSync,writeFileSync } from "node:fs";
import {status as alpha} from "./features/alpha.mjs";
import {status as beta} from "./features/beta.mjs";
mkdirSync("generated",{recursive:true});writeFileSync("generated/index.json",JSON.stringify([{status:alpha},{status:beta}]));
